const DATA_LED_APPROVED = [{"id":"LED-20261009-0001","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 170, caput e incisos I a V","number":"Art. 170, caput e incisos I a V","title":"Constituição Federal de 1988","parts":["Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nI - soberania nacional;\nII - propriedade privada;\nIII - função social da propriedade;\nIV - livre concorrência;\nV - defesa do consumidor;"],"origin":"authorial","question":{"statement":"Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nI - soberania nacional;\nII - propriedade privada;\nIII - função social da propriedade;\nIV - livre concorrência;\nV - defesa do consumidor;","answer":true,"explanation":"O caput fixa o fundamento e a finalidade da ordem econômica; os cinco primeiros incisos enumeram princípios distintos.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0002","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 170, caput e inciso VI","number":"Art. 170, caput e inciso VI","title":"Constituição Federal de 1988","parts":["Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nVI - defesa do meio ambiente, inclusive mediante tratamento diferenciado conforme o impacto ambiental dos produtos e serviços e de seus processos de elaboração e prestação;"],"origin":"authorial","question":{"statement":"Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nVI - defesa do meio ambiente, inclusive mediante tratamento diferenciado conforme o impacto ambiental dos produtos e de seus processos de elaboração e prestação;","answer":false,"explanation":"A defesa ambiental abrange o impacto dos produtos e dos serviços, bem como seus processos de elaboração e prestação.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0003","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 170, caput e incisos VII e VIII","number":"Art. 170, caput e incisos VII e VIII","title":"Constituição Federal de 1988","parts":["Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nVII - redução das desigualdades regionais e sociais;\nVIII - busca do pleno emprego;"],"origin":"authorial","question":{"statement":"Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nVII - redução das desigualdades regionais e sociais;\nVIII - busca do pleno emprego;","answer":true,"explanation":"A redução das desigualdades regionais e sociais e a busca do pleno emprego são princípios expressos.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0004","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 170, caput e inciso IX","number":"Art. 170, caput e inciso IX","title":"Constituição Federal de 1988","parts":["Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nIX - tratamento favorecido para as empresas de pequeno porte constituídas sob as leis brasileiras e que tenham sua sede e administração no País."],"origin":"authorial","question":{"statement":"Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nIX - tratamento favorecido para as empresas de pequeno porte constituídas sob as leis brasileiras e que tenham sua sede ou administração no País.","answer":false,"explanation":"O tratamento favorecido exige cumulativamente sede e administração no País, além da constituição sob as leis brasileiras.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0005","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 170, parágrafo único","number":"Art. 170, parágrafo único","title":"Constituição Federal de 1988","parts":["Parágrafo único. É assegurado a todos o livre exercício de qualquer atividade econômica, independentemente de autorização de órgãos públicos, salvo nos casos previstos em lei."],"origin":"authorial","question":{"statement":"Parágrafo único. É assegurado a todos o livre exercício de qualquer atividade econômica, independentemente de autorização de órgãos públicos, salvo nos casos previstos em regulamento.","answer":false,"explanation":"A exceção à dispensa de autorização depende de previsão em lei, e não apenas de regulamento.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0006","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 172, caput","number":"Art. 172, caput","title":"Constituição Federal de 1988","parts":["Art. 172. A lei disciplinará, com base no interesse nacional, os investimentos de capital estrangeiro, incentivará os reinvestimentos e regulará a remessa de lucros."],"origin":"authorial","question":{"statement":"Art. 172. A lei disciplinará, com base no interesse nacional, os investimentos de capital estrangeiro, incentivará os reinvestimentos e regulará a remessa de lucros.","answer":true,"explanation":"A lei disciplina o investimento estrangeiro com base no interesse nacional, incentiva reinvestimentos e regula a remessa de lucros.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0007","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, caput","number":"Art. 173, caput","title":"Constituição Federal de 1988","parts":["Art. 173. Ressalvados os casos previstos nesta Constituição, a exploração direta de atividade econômica pelo Estado só será permitida quando necessária aos imperativos da segurança nacional ou a relevante interesse coletivo, conforme definidos em lei."],"origin":"authorial","question":{"statement":"Art. 173. Ressalvados os casos previstos nesta Constituição, a exploração direta de atividade econômica pelo Estado só será permitida quando necessária aos imperativos da segurança nacional e a relevante interesse coletivo, conforme definidos em lei.","answer":false,"explanation":"Segurança nacional e relevante interesse coletivo são fundamentos alternativos para a exploração direta, conforme definidos em lei.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0008","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 1º, caput e inciso I","number":"Art. 173, § 1º, caput e inciso I","title":"Constituição Federal de 1988","parts":["§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nI - sua função social e formas de fiscalização pelo Estado e pela sociedade;"],"origin":"authorial","question":{"statement":"§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nI - sua função social e formas de fiscalização pelo Estado e pela sociedade;","answer":true,"explanation":"O estatuto jurídico deve tratar da função social e da fiscalização pelo Estado e pela sociedade.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0009","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 1º, caput e inciso II","number":"Art. 173, § 1º, caput e inciso II","title":"Constituição Federal de 1988","parts":["§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nII - a sujeição ao regime jurídico próprio das empresas privadas, inclusive quanto aos direitos e obrigações civis, comerciais, trabalhistas e tributários;"],"origin":"authorial","question":{"statement":"§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nII - a sujeição ao regime jurídico próprio das entidades de direito público, inclusive quanto aos direitos e obrigações civis, comerciais, trabalhistas e tributários;","answer":false,"explanation":"A sujeição indicada é ao regime jurídico próprio das empresas privadas, inclusive nas obrigações enumeradas.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0010","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 1º, caput e inciso III","number":"Art. 173, § 1º, caput e inciso III","title":"Constituição Federal de 1988","parts":["§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nIII - licitação e contratação de obras, serviços, compras e alienações, observados os princípios da administração pública;"],"origin":"authorial","question":{"statement":"§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nIII - licitação e contratação de obras, serviços, compras e alienações, observados os princípios da administração pública;","answer":true,"explanation":"Licitação e contratação de obras, serviços, compras e alienações devem constar do estatuto, observados os princípios da administração pública.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0011","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 1º, caput e inciso IV","number":"Art. 173, § 1º, caput e inciso IV","title":"Constituição Federal de 1988","parts":["§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nIV - a constituição e o funcionamento dos conselhos de administração e fiscal, com a participação de acionistas minoritários;"],"origin":"authorial","question":{"statement":"§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nIV - a constituição e o funcionamento dos conselhos de administração e fiscal, com a participação de acionistas majoritários;","answer":false,"explanation":"O inciso prevê participação de acionistas minoritários nos conselhos de administração e fiscal; não a restringe aos majoritários.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0012","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 1º, caput e inciso V","number":"Art. 173, § 1º, caput e inciso V","title":"Constituição Federal de 1988","parts":["§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nV - os mandatos, a avaliação de desempenho e a responsabilidade dos administradores."],"origin":"authorial","question":{"statement":"§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nV - os mandatos, a avaliação de desempenho e a responsabilidade dos administradores.","answer":true,"explanation":"Mandatos, avaliação de desempenho e responsabilidade dos administradores compõem o conteúdo do estatuto jurídico.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0013","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 2º","number":"Art. 173, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º As empresas públicas e as sociedades de economia mista não poderão gozar de privilégios fiscais não extensivos às do setor privado."],"origin":"authorial","question":{"statement":"§ 2º As empresas públicas e as sociedades de economia mista não poderão gozar de privilégios fiscais não extensivos às do setor privado.","answer":true,"explanation":"A vedação alcança somente privilégios fiscais que não se estendam às empresas do setor privado.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0014","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 3º","number":"Art. 173, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º A lei regulamentará as relações da empresa pública com o Estado e a sociedade."],"origin":"authorial","question":{"statement":"§ 3º O decreto regulamentará as relações da empresa pública com o Estado e a sociedade.","answer":false,"explanation":"A Constituição atribui à lei a regulamentação das relações da empresa pública com o Estado e a sociedade.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0015","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 4º","number":"Art. 173, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º A lei reprimirá o abuso do poder econômico que vise à dominação dos mercados, à eliminação da concorrência e ao aumento arbitrário dos lucros."],"origin":"authorial","question":{"statement":"§ 4º A lei reprimirá o abuso do poder econômico que vise à dominação dos mercados, à eliminação da concorrência e ao aumento arbitrário dos lucros.","answer":true,"explanation":"A repressão legal mira o abuso voltado à dominação de mercados, à eliminação da concorrência e ao aumento arbitrário dos lucros.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0016","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 5º","number":"Art. 173, § 5º","title":"Constituição Federal de 1988","parts":["§ 5º A lei, sem prejuízo da responsabilidade individual dos dirigentes da pessoa jurídica, estabelecerá a responsabilidade desta, sujeitando-a às punições compatíveis com sua natureza, nos atos praticados contra a ordem econômica e financeira e contra a economia popular."],"origin":"authorial","question":{"statement":"§ 5º A lei, em substituição à responsabilidade individual dos dirigentes da pessoa jurídica, estabelecerá a responsabilidade desta, sujeitando-a às punições compatíveis com sua natureza, nos atos praticados contra a ordem econômica e financeira e contra a economia popular.","answer":false,"explanation":"A responsabilidade da pessoa jurídica não afasta a responsabilidade individual dos dirigentes.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0017","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 174, caput","number":"Art. 174, caput","title":"Constituição Federal de 1988","parts":["Art. 174. Como agente normativo e regulador da atividade econômica, o Estado exercerá, na forma da lei, as funções de fiscalização, incentivo e planejamento, sendo este determinante para o setor público e indicativo para o setor privado."],"origin":"authorial","question":{"statement":"Art. 174. Como agente normativo e regulador da atividade econômica, o Estado exercerá, na forma da lei, as funções de fiscalização, incentivo e planejamento, sendo este indicativo para o setor público e determinante para o setor privado.","answer":false,"explanation":"O planejamento é determinante para o setor público e indicativo para o setor privado.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0018","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 174, § 1º","number":"Art. 174, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º A lei estabelecerá as diretrizes e bases do planejamento do desenvolvimento nacional equilibrado, o qual incorporará e compatibilizará os planos nacionais e regionais de desenvolvimento."],"origin":"authorial","question":{"statement":"§ 1º A lei estabelecerá as diretrizes e bases do planejamento do desenvolvimento nacional equilibrado, o qual incorporará e compatibilizará os planos nacionais e regionais de desenvolvimento.","answer":true,"explanation":"O planejamento nacional equilibrado incorpora e compatibiliza planos nacionais e regionais de desenvolvimento.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0019","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 174, § 2º","number":"Art. 174, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º A lei apoiará e estimulará o cooperativismo e outras formas de associativismo."],"origin":"authorial","question":{"statement":"§ 2º A lei poderá apoiar e estimular o cooperativismo e outras formas de associativismo.","answer":false,"explanation":"O dispositivo estabelece que a lei apoiará e estimulará o cooperativismo e outras formas de associativismo.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0020","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 174, § 3º","number":"Art. 174, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º O Estado favorecerá a organização da atividade garimpeira em cooperativas, levando em conta a proteção do meio ambiente e a promoção econômico-social dos garimpeiros."],"origin":"authorial","question":{"statement":"§ 3º O Estado favorecerá a organização da atividade garimpeira em cooperativas, levando em conta a proteção do meio ambiente e a promoção econômico-social dos garimpeiros.","answer":true,"explanation":"A organização da atividade garimpeira em cooperativas deve considerar proteção ambiental e promoção econômico-social dos garimpeiros.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0021","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 174, §§ 3º e 4º","number":"Art. 174, §§ 3º e 4º","title":"Constituição Federal de 1988","parts":["§ 3º O Estado favorecerá a organização da atividade garimpeira em cooperativas, levando em conta a proteção do meio ambiente e a promoção econômico-social dos garimpeiros.\n§ 4º As cooperativas a que se refere o parágrafo anterior terão prioridade na autorização ou concessão para pesquisa e lavra dos recursos e jazidas de minerais garimpáveis, nas áreas onde estejam atuando, e naquelas fixadas de acordo com o art. 21, XXV, na forma da lei."],"origin":"authorial","question":{"statement":"§ 3º O Estado favorecerá a organização da atividade garimpeira em cooperativas, levando em conta a proteção do meio ambiente e a promoção econômico-social dos garimpeiros.\n§ 4º As cooperativas a que se refere o parágrafo anterior terão exclusividade na autorização ou concessão para pesquisa e lavra dos recursos e jazidas de minerais garimpáveis, nas áreas onde estejam atuando, e naquelas fixadas de acordo com o art. 21, XXV, na forma da lei.","answer":false,"explanation":"As cooperativas referidas no § 3º têm prioridade, e não exclusividade, nas áreas indicadas no § 4º.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0022","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 175, caput","number":"Art. 175, caput","title":"Constituição Federal de 1988","parts":["Art. 175. Incumbe ao Poder Público, na forma da lei, diretamente ou sob regime de concessão ou permissão, sempre através de licitação, a prestação de serviços públicos."],"origin":"authorial","question":{"statement":"Art. 175. Incumbe ao Poder Público, na forma da lei, diretamente ou sob regime de concessão ou autorização, sempre através de licitação, a prestação de serviços públicos.","answer":false,"explanation":"A prestação direta ou delegada por concessão ou permissão é incumbência do Poder Público; a delegação indicada exige licitação.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0023","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 175, parágrafo único, inciso I","number":"Art. 175, parágrafo único, inciso I","title":"Constituição Federal de 1988","parts":["Parágrafo único. A lei disporá sobre:\nI - o regime das empresas concessionárias e permissionárias de serviços públicos, o caráter especial de seu contrato e de sua prorrogação, bem como as condições de caducidade, fiscalização e rescisão da concessão ou permissão;"],"origin":"authorial","question":{"statement":"Parágrafo único. A lei disporá sobre:\nI - o regime das empresas concessionárias e permissionárias de serviços públicos, o caráter especial de seu contrato e de sua prorrogação, bem como as condições de caducidade, fiscalização e rescisão da concessão ou permissão;","answer":true,"explanation":"A lei deve tratar do regime das concessionárias e permissionárias, do contrato e de sua prorrogação e das condições de caducidade, fiscalização e rescisão.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0024","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 175, parágrafo único, incisos II e III","number":"Art. 175, parágrafo único, incisos II e III","title":"Constituição Federal de 1988","parts":["Parágrafo único. A lei disporá sobre:\nII - os direitos dos usuários;\nIII - política tarifária;"],"origin":"authorial","question":{"statement":"Parágrafo único. A lei disporá sobre:\nII - os direitos dos usuários;\nIII - política tarifária;","answer":true,"explanation":"Direitos dos usuários e política tarifária são matérias expressamente reservadas à lei.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0025","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 175, parágrafo único, inciso IV","number":"Art. 175, parágrafo único, inciso IV","title":"Constituição Federal de 1988","parts":["Parágrafo único. A lei disporá sobre:\nIV - a obrigação de manter serviço adequado."],"origin":"authorial","question":{"statement":"Parágrafo único. A lei disporá sobre:\nIV - a obrigação de manter serviço contínuo.","answer":false,"explanation":"O texto exige serviço adequado; continuidade isolada não reproduz todo o comando do inciso.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0026","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 176, caput","number":"Art. 176, caput","title":"Constituição Federal de 1988","parts":["Art. 176. As jazidas, em lavra ou não, e demais recursos minerais e os potenciais de energia hidráulica constituem propriedade distinta da do solo, para efeito de exploração ou aproveitamento, e pertencem à União, garantida ao concessionário a propriedade do produto da lavra."],"origin":"authorial","question":{"statement":"Art. 176. As jazidas, em lavra ou não, e demais recursos minerais e os potenciais de energia hidráulica constituem propriedade distinta da do solo, para efeito de exploração ou aproveitamento, e pertencem à União, garantida ao concessionário a propriedade do produto da lavra.","answer":true,"explanation":"As jazidas e potenciais hidráulicos são propriedade distinta da do solo e pertencem à União; o concessionário tem a propriedade do produto da lavra.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0027","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 176, § 1º","number":"Art. 176, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º A pesquisa e a lavra de recursos minerais e o aproveitamento dos potenciais a que se refere o \"caput\" deste artigo somente poderão ser efetuados mediante autorização ou concessão da União, no interesse nacional, por brasileiros ou empresa constituída sob as leis brasileiras e que tenha sua sede e administração no País, na forma da lei, que estabelecerá as condições específicas quando essas atividades se desenvolverem em faixa de fronteira ou terras indígenas."],"origin":"authorial","question":{"statement":"§ 1º A pesquisa e a lavra de recursos minerais e o aproveitamento dos potenciais a que se refere o \"caput\" deste artigo somente poderão ser efetuados mediante autorização ou concessão da União, no interesse nacional, por brasileiros ou empresa constituída sob as leis brasileiras e que tenha sua sede ou administração no País, na forma da lei, que estabelecerá as condições específicas quando essas atividades se desenvolverem em faixa de fronteira ou terras indígenas.","answer":false,"explanation":"A empresa deve ter sede e administração no País, requisitos cumulativos, além de ser constituída sob as leis brasileiras.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0028","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 176, § 2º","number":"Art. 176, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º É assegurada participação ao proprietário do solo nos resultados da lavra, na forma e no valor que dispuser a lei."],"origin":"authorial","question":{"statement":"§ 2º É assegurada participação ao Município onde se situa a jazida nos resultados da lavra, na forma e no valor que dispuser a lei.","answer":false,"explanation":"A participação nos resultados da lavra é assegurada ao proprietário do solo, na forma e no valor definidos em lei.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0029","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 176, § 3º","number":"Art. 176, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º A autorização de pesquisa será sempre por prazo determinado, e as autorizações e concessões previstas neste artigo não poderão ser cedidas ou transferidas, total ou parcialmente, sem prévia anuência do poder concedente."],"origin":"authorial","question":{"statement":"§ 3º A autorização de pesquisa será sempre por prazo determinado, e as autorizações e concessões previstas neste artigo não poderão ser cedidas ou transferidas, total ou parcialmente, sem prévia anuência do poder concedente.","answer":true,"explanation":"A autorização de pesquisa tem prazo determinado, e a cessão ou transferência requer anuência prévia do poder concedente.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0030","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 176, § 4º","number":"Art. 176, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º Não dependerá de autorização ou concessão o aproveitamento do potencial de energia renovável de capacidade reduzida."],"origin":"authorial","question":{"statement":"§ 4º Não dependerá de autorização ou concessão o aproveitamento do potencial de energia renovável de capacidade reduzida.","answer":true,"explanation":"O aproveitamento do potencial de energia renovável de capacidade reduzida dispensa autorização ou concessão.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0031","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, caput e incisos I e II","number":"Art. 177, caput e incisos I e II","title":"Constituição Federal de 1988","parts":["Art. 177. Constituem monopólio da União:\nI - a pesquisa e a lavra das jazidas de petróleo e gás natural e outros hidrocarbonetos fluidos;\nII - a refinação do petróleo nacional ou estrangeiro;"],"origin":"authorial","question":{"statement":"Art. 177. Constituem monopólio da União:\nI - a pesquisa e a lavra das jazidas de petróleo e gás natural e outros hidrocarbonetos fluidos;\nII - a refinação do petróleo nacional ou estrangeiro;","answer":true,"explanation":"Pesquisa e lavra de petróleo, gás natural e outros hidrocarbonetos fluidos, bem como refinação de petróleo nacional ou estrangeiro, integram o monopólio da União.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0032","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, caput e incisos III e IV","number":"Art. 177, caput e incisos III e IV","title":"Constituição Federal de 1988","parts":["Art. 177. Constituem monopólio da União:\nIII - a importação e exportação dos produtos e derivados básicos resultantes das atividades previstas nos incisos anteriores;\nIV - o transporte marítimo do petróleo bruto de origem nacional ou de derivados básicos de petróleo produzidos no País, bem assim o transporte, por meio de conduto, de petróleo bruto, seus derivados e gás natural de qualquer origem;"],"origin":"authorial","question":{"statement":"Art. 177. Constituem monopólio da União:\nIII - a importação e exportação dos produtos e derivados básicos resultantes das atividades previstas nos incisos anteriores;\nIV - o transporte marítimo do petróleo bruto de qualquer origem ou de derivados básicos de petróleo produzidos no País, bem assim o transporte, por meio de conduto, de petróleo bruto, seus derivados e gás natural de qualquer origem;","answer":false,"explanation":"No transporte marítimo, o inciso IV especifica petróleo bruto de origem nacional; a expressão “de qualquer origem” qualifica o transporte por conduto.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0033","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, caput e inciso V","number":"Art. 177, caput e inciso V","title":"Constituição Federal de 1988","parts":["Art. 177. Constituem monopólio da União:\nV - a pesquisa, a lavra, o enriquecimento, o reprocessamento, a industrialização e o comércio de minérios e minerais nucleares e seus derivados, com exceção dos radioisótopos cuja produção, comercialização e utilização poderão ser autorizadas sob regime de permissão, conforme as alíneas b e c do inciso XXIII do caput do art. 21 desta Constituição Federal."],"origin":"authorial","question":{"statement":"Art. 177. Constituem monopólio da União:\nV - a pesquisa, a lavra, o enriquecimento, o reprocessamento, a industrialização e o comércio de minérios e minerais nucleares e seus derivados, com exceção dos radioisótopos cuja produção, comercialização e utilização poderão ser autorizadas sob regime de permissão, conforme as alíneas b e c do inciso XXIII do caput do art. 21 desta Constituição Federal.","answer":true,"explanation":"O inciso V permanece vigente e ressalva os radioisótopos autorizáveis por permissão nos termos da remissão ao art. 21. O inciso estava ausente do anexo.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0034","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 1º","number":"Art. 177, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º A União poderá contratar com empresas estatais ou privadas a realização das atividades previstas nos incisos I a IV deste artigo observadas as condições estabelecidas em lei."],"origin":"authorial","question":{"statement":"§ 1º A União poderá contratar somente com empresas estatais a realização das atividades previstas nos incisos I a IV deste artigo observadas as condições estabelecidas em lei.","answer":false,"explanation":"A União pode contratar empresas estatais ou privadas para as atividades dos incisos I a IV, nas condições legais.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0035","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 2º, caput e inciso I","number":"Art. 177, § 2º, caput e inciso I","title":"Constituição Federal de 1988","parts":["§ 2º A lei a que se refere o § 1º disporá sobre:\nI - a garantia do fornecimento dos derivados de petróleo em todo o território nacional;"],"origin":"authorial","question":{"statement":"§ 2º A lei a que se refere o § 1º disporá sobre:\nI - a garantia do fornecimento dos derivados de petróleo em todo o território nacional;","answer":true,"explanation":"A lei referida no § 1º deve garantir o fornecimento de derivados de petróleo em todo o território nacional.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0036","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 2º, caput e incisos II e III","number":"Art. 177, § 2º, caput e incisos II e III","title":"Constituição Federal de 1988","parts":["§ 2º A lei a que se refere o § 1º disporá sobre:\nII - as condições de contratação;\nIII - a estrutura e atribuições do órgão regulador do monopólio da União;"],"origin":"authorial","question":{"statement":"§ 2º A lei a que se refere o § 1º disporá sobre:\nII - as condições de contratação;\nIII - a estrutura e atribuições do órgão executor do monopólio da União;","answer":false,"explanation":"A lei trata das condições de contratação e da estrutura e atribuições do órgão regulador, não de um órgão executor.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0037","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 3º","number":"Art. 177, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º A lei disporá sobre o transporte e a utilização de materiais radioativos no território nacional."],"origin":"authorial","question":{"statement":"§ 3º A lei disporá sobre o transporte e a utilização de materiais radioativos no território nacional.","answer":true,"explanation":"A lei dispõe sobre transporte e utilização de materiais radioativos no território nacional.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0038","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 4º, caput, inciso I, alínea a","number":"Art. 177, § 4º, caput, inciso I, alínea a","title":"Constituição Federal de 1988","parts":["§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nI - a alíquota da contribuição poderá ser:\na) diferenciada por produto ou uso;"],"origin":"authorial","question":{"statement":"§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nI - a alíquota da contribuição poderá ser:\na) diferenciada por produto ou uso;","answer":true,"explanation":"A alíquota da contribuição indicada no caput pode ser diferenciada por produto ou uso.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0039","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 4º, caput, inciso I, alínea b","number":"Art. 177, § 4º, caput, inciso I, alínea b","title":"Constituição Federal de 1988","parts":["§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nI - a alíquota da contribuição poderá ser:\nb) reduzida e restabelecida por ato do Poder Executivo, não se lhe aplicando o disposto no art. 150,III, b;"],"origin":"authorial","question":{"statement":"§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nI - a alíquota da contribuição poderá ser:\nb) reduzida e restabelecida por lei específica, não se lhe aplicando o disposto no art. 150,III, b;","answer":false,"explanation":"A redução e o restabelecimento da alíquota podem ocorrer por ato do Poder Executivo, com a exceção à anterioridade mencionada na alínea.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0040","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 4º, caput, inciso II, alínea a","number":"Art. 177, § 4º, caput, inciso II, alínea a","title":"Constituição Federal de 1988","parts":["§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nII - os recursos arrecadados serão destinados:\na) ao pagamento de subsídios a preços ou transporte de álcool combustível, gás natural e seus derivados e derivados de petróleo;"],"origin":"authorial","question":{"statement":"§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nII - os recursos arrecadados serão destinados:\na) ao pagamento de subsídios apenas ao transporte de álcool combustível, gás natural e seus derivados e derivados de petróleo;","answer":false,"explanation":"A destinação permite subsídios a preços ou ao transporte dos produtos enumerados; não se limita ao transporte.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0041","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 4º, caput, inciso II, alíneas b e c","number":"Art. 177, § 4º, caput, inciso II, alíneas b e c","title":"Constituição Federal de 1988","parts":["§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nII - os recursos arrecadados serão destinados:\nb) ao financiamento de projetos ambientais relacionados com a indústria do petróleo e do gás;\nc) ao financiamento de programas de infra-estrutura de transportes."],"origin":"authorial","question":{"statement":"§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nII - os recursos arrecadados serão destinados:\nb) ao financiamento de projetos ambientais relacionados com a indústria do petróleo e do gás;\nc) ao financiamento de programas de infra-estrutura de transportes.","answer":true,"explanation":"Projetos ambientais ligados à indústria de petróleo e gás e programas de infraestrutura de transportes são destinos previstos.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0042","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 4º, caput, inciso II, alínea d","number":"Art. 177, § 4º, caput, inciso II, alínea d","title":"Constituição Federal de 1988","parts":["§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nII - os recursos arrecadados serão destinados:\nd) ao pagamento de subsídios a tarifas de transporte público coletivo de passageiros."],"origin":"authorial","question":{"statement":"§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nII - os recursos arrecadados serão destinados:\nd) ao pagamento de subsídios a tarifas de transporte privado de passageiros.","answer":false,"explanation":"A alínea acrescentada pela EC 132/2023 prevê subsídio a tarifas de transporte público coletivo de passageiros.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0043","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 178, caput","number":"Art. 178, caput","title":"Constituição Federal de 1988","parts":["Art. 178. A lei disporá sobre a ordenação dos transportes aéreo, aquático e terrestre, devendo, quanto à ordenação do transporte internacional, observar os acordos firmados pela União, atendido o princípio da reciprocidade."],"origin":"authorial","question":{"statement":"Art. 178. A lei disporá sobre a ordenação dos transportes aéreo, aquático e terrestre, devendo, quanto à ordenação do transporte internacional, observar os acordos firmados pelos Estados, atendido o princípio da reciprocidade.","answer":false,"explanation":"Na ordenação do transporte internacional, devem ser observados os acordos firmados pela União e o princípio da reciprocidade.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0044","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 178, parágrafo único","number":"Art. 178, parágrafo único","title":"Constituição Federal de 1988","parts":["Parágrafo único. Na ordenação do transporte aquático, a lei estabelecerá as condições em que o transporte de mercadorias na cabotagem e a navegação interior poderão ser feitos por embarcações estrangeiras."],"origin":"authorial","question":{"statement":"Parágrafo único. Na ordenação do transporte aquático, a lei estabelecerá as condições em que o transporte de mercadorias na cabotagem e a navegação interior poderão ser feitos por embarcações estrangeiras.","answer":true,"explanation":"A lei define quando embarcações estrangeiras podem realizar cabotagem e navegação interior no transporte de mercadorias.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0045","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 179, caput","number":"Art. 179, caput","title":"Constituição Federal de 1988","parts":["Art. 179. A União, os Estados, o Distrito Federal e os Municípios dispensarão às microempresas e às empresas de pequeno porte, assim definidas em lei, tratamento jurídico diferenciado, visando a incentivá-las pela simplificação de suas obrigações administrativas, tributárias, previdenciárias e creditícias, ou pela eliminação ou redução destas por meio de lei."],"origin":"authorial","question":{"statement":"Art. 179. A União, os Estados, o Distrito Federal e os Municípios dispensarão às microempresas e às empresas de pequeno porte, assim definidas em lei, tratamento jurídico diferenciado, visando a incentivá-las pela simplificação de suas obrigações administrativas, tributárias, previdenciárias e creditícias, ou pela eliminação ou redução destas por meio de decreto.","answer":false,"explanation":"A eliminação ou redução das obrigações indicadas deve ocorrer por meio de lei.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0046","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 180, caput","number":"Art. 180, caput","title":"Constituição Federal de 1988","parts":["Art. 180. A União, os Estados, o Distrito Federal e os Municípios promoverão e incentivarão o turismo como fator de desenvolvimento social e econômico."],"origin":"authorial","question":{"statement":"Art. 180. A União, os Estados, o Distrito Federal e os Municípios promoverão e incentivarão o turismo como fator de desenvolvimento social e econômico.","answer":true,"explanation":"A promoção do turismo cabe aos quatro níveis federativos, como fator de desenvolvimento social e econômico.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0047","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 181, caput","number":"Art. 181, caput","title":"Constituição Federal de 1988","parts":["Art. 181. O atendimento de requisição de documento ou informação de natureza comercial, feita por autoridade administrativa ou judiciária estrangeira, a pessoa física ou jurídica residente ou domiciliada no País dependerá de autorização do Poder competente."],"origin":"authorial","question":{"statement":"Art. 181. O atendimento de requisição de documento ou informação de natureza comercial, feita por autoridade administrativa ou judiciária estrangeira, a pessoa física ou jurídica residente ou domiciliada no exterior dependerá de autorização do Poder competente.","answer":false,"explanation":"O dispositivo se refere à pessoa física ou jurídica residente ou domiciliada no País, diante de requisição de autoridade estrangeira.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0048","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 193, caput","number":"Art. 193, caput","title":"Constituição Federal de 1988","parts":["Art. 193. A ordem social tem como base o primado do trabalho, e como objetivo o bem-estar e a justiça sociais."],"origin":"authorial","question":{"statement":"Art. 193. A ordem social tem como base o primado do trabalho, e como objetivo o bem-estar e a justiça sociais.","answer":true,"explanation":"O primado do trabalho é a base da ordem social; seus objetivos são o bem-estar e a justiça sociais.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0049","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 193, parágrafo único","number":"Art. 193, parágrafo único","title":"Constituição Federal de 1988","parts":["Parágrafo único. O Estado exercerá a função de planejamento das políticas sociais, assegurada, na forma da lei, a participação da sociedade nos processos de formulação, de monitoramento, de controle e de avaliação dessas políticas."],"origin":"authorial","question":{"statement":"Parágrafo único. O Estado exercerá a função de planejamento das políticas sociais, assegurada, independentemente de lei, a participação da sociedade nos processos de formulação, de monitoramento, de controle e de avaliação dessas políticas.","answer":false,"explanation":"A participação da sociedade nos processos enumerados é assegurada na forma da lei.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0050","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, caput","number":"Art. 194, caput","title":"Constituição Federal de 1988","parts":["Art. 194. A seguridade social compreende um conjunto integrado de ações de iniciativa dos Poderes Públicos e da sociedade, destinadas a assegurar os direitos relativos à saúde, à previdência e à assistência social."],"origin":"authorial","question":{"statement":"Art. 194. A seguridade social compreende um conjunto integrado de ações de iniciativa dos Poderes Públicos e da sociedade, destinadas a assegurar os direitos relativos à saúde, à previdência e à assistência social.","answer":true,"explanation":"A seguridade integra ações dos Poderes Públicos e da sociedade e alcança saúde, previdência e assistência social.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0051","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso I","number":"Art. 194, parágrafo único, inciso I","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nI - universalidade da cobertura e do atendimento;"],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nI - universalidade da cobertura e seletividade do atendimento;","answer":false,"explanation":"O inciso estabelece universalidade tanto da cobertura quanto do atendimento; seletividade aparece em outro objetivo.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0052","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso II","number":"Art. 194, parágrafo único, inciso II","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nII - uniformidade e equivalência dos benefícios e serviços às populações urbanas e rurais;"],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nII - uniformidade e equivalência dos benefícios e serviços às populações urbanas e rurais;","answer":true,"explanation":"Uniformidade e equivalência dos benefícios e serviços abrangem as populações urbanas e rurais.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0053","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso III","number":"Art. 194, parágrafo único, inciso III","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nIII - seletividade e distributividade na prestação dos benefícios e serviços;"],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nIII - uniformidade e distributividade na prestação dos benefícios e serviços;","answer":false,"explanation":"A prestação dos benefícios e serviços deve observar seletividade e distributividade; uniformidade integra o inciso II.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0054","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso IV","number":"Art. 194, parágrafo único, inciso IV","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nIV - irredutibilidade do valor dos benefícios;"],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nIV - irredutibilidade do valor dos benefícios;","answer":true,"explanation":"A irredutibilidade do valor dos benefícios é objetivo expresso da organização da seguridade.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0055","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso V","number":"Art. 194, parágrafo único, inciso V","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nV - eqüidade na forma de participação no custeio;"],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nV - igualdade na forma de participação no custeio;","answer":false,"explanation":"O texto usa equidade na participação no custeio, e não igualdade uniforme entre todos.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0056","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso VI","number":"Art. 194, parágrafo único, inciso VI","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nVI - diversidade da base de financiamento, identificando-se, em rubricas contábeis específicas para cada área, as receitas e as despesas vinculadas a ações de saúde, previdência e assistência social, preservado o caráter contributivo da previdência social;"],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nVI - diversidade da base de financiamento, identificando-se, em rubricas contábeis específicas para cada área, as receitas e as despesas vinculadas a ações de saúde, previdência e assistência social, preservado o caráter contributivo da previdência social;","answer":true,"explanation":"A diversidade da base de financiamento exige rubricas específicas por área e preserva o caráter contributivo da previdência social.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0057","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso VII","number":"Art. 194, parágrafo único, inciso VII","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nVII - caráter democrático e descentralizado da administração, mediante gestão quadripartite, com participação dos trabalhadores, dos empregadores, dos aposentados e do Governo nos órgãos colegiados."],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nVII - caráter democrático e descentralizado da administração, mediante gestão tripartite, com participação dos trabalhadores, dos empregadores, dos aposentados e do Governo nos órgãos colegiados.","answer":false,"explanation":"A gestão é quadripartite, com trabalhadores, empregadores, aposentados e Governo nos colegiados.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0058","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 196, caput","number":"Art. 196, caput","title":"Constituição Federal de 1988","parts":["Art. 196. A saúde é direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas que visem à redução do risco de doença e de outros agravos e ao acesso universal e igualitário às ações e serviços para sua promoção, proteção e recuperação."],"origin":"authorial","question":{"statement":"Art. 196. A saúde é direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas que visem à redução do risco de doença e de outros agravos e ao acesso universal e seletivo às ações e serviços para sua promoção, proteção e recuperação.","answer":false,"explanation":"O acesso às ações e serviços de saúde é universal e igualitário, para promoção, proteção e recuperação.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0059","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 197, caput","number":"Art. 197, caput","title":"Constituição Federal de 1988","parts":["Art. 197. São de relevância pública as ações e serviços de saúde, cabendo ao Poder Público dispor, nos termos da lei, sobre sua regulamentação, fiscalização e controle, devendo sua execução ser feita diretamente ou através de terceiros e, também, por pessoa física ou jurídica de direito privado."],"origin":"authorial","question":{"statement":"Art. 197. São de relevância pública as ações e serviços de saúde, cabendo ao Poder Público dispor, nos termos da lei, sobre sua regulamentação, fiscalização e controle, devendo sua execução ser feita diretamente ou através de terceiros e, também, por pessoa física ou jurídica de direito privado.","answer":true,"explanation":"Ações e serviços de saúde têm relevância pública; a execução pode ocorrer diretamente, por terceiros ou por pessoas privadas.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0060","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, caput e inciso I","number":"Art. 198, caput e inciso I","title":"Constituição Federal de 1988","parts":["Art. 198. As ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as seguintes diretrizes:\nI - descentralização, com direção única em cada esfera de governo;"],"origin":"authorial","question":{"statement":"Art. 198. As ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as seguintes diretrizes:\nI - descentralização, com direção centralizada na União;","answer":false,"explanation":"A descentralização do SUS vem acompanhada de direção única em cada esfera de governo.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0061","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, caput e inciso II","number":"Art. 198, caput e inciso II","title":"Constituição Federal de 1988","parts":["Art. 198. As ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as seguintes diretrizes:\nII - atendimento integral, com prioridade para as atividades preventivas, sem prejuízo dos serviços assistenciais;"],"origin":"authorial","question":{"statement":"Art. 198. As ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as seguintes diretrizes:\nII - atendimento integral, com prioridade para as atividades preventivas, sem prejuízo dos serviços assistenciais;","answer":true,"explanation":"O atendimento integral prioriza prevenção sem prejudicar os serviços assistenciais.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0062","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, caput e inciso III","number":"Art. 198, caput e inciso III","title":"Constituição Federal de 1988","parts":["Art. 198. As ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as seguintes diretrizes:\nIII - participação da comunidade."],"origin":"authorial","question":{"statement":"Art. 198. As ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as seguintes diretrizes:\nIII - participação dos prestadores privados.","answer":false,"explanation":"A diretriz constitucional é a participação da comunidade.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0063","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 1º","number":"Art. 198, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º O sistema único de saúde será financiado, nos termos do art. 195, com recursos do orçamento da seguridade social, da União, dos Estados, do Distrito Federal e dos Municípios, além de outras fontes."],"origin":"authorial","question":{"statement":"§ 1º O sistema único de saúde será financiado, nos termos do art. 195, com recursos do orçamento da seguridade social, da União, dos Estados, do Distrito Federal e dos Municípios, vedadas outras fontes.","answer":false,"explanation":"O financiamento do SUS inclui os recursos indicados e admite outras fontes.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0064","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 2º, caput e inciso I","number":"Art. 198, § 2º, caput e inciso I","title":"Constituição Federal de 1988","parts":["§ 2º A União, os Estados, o Distrito Federal e os Municípios aplicarão, anualmente, em ações e serviços públicos de saúde recursos mínimos derivados da aplicação de percentuais calculados sobre:\nI - no caso da União, a receita corrente líquida do respectivo exercício financeiro, não podendo ser inferior a 15% (quinze por cento);"],"origin":"authorial","question":{"statement":"§ 2º A União, os Estados, o Distrito Federal e os Municípios aplicarão, anualmente, em ações e serviços públicos de saúde recursos mínimos derivados da aplicação de percentuais calculados sobre:\nI - no caso da União, a receita corrente líquida do respectivo exercício financeiro, não podendo ser inferior a 15% (quinze por cento);","answer":true,"explanation":"O mínimo da União é calculado sobre a receita corrente líquida do exercício e não pode ficar abaixo de 15%.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0065","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 2º, caput e inciso II","number":"Art. 198, § 2º, caput e inciso II","title":"Constituição Federal de 1988","parts":["§ 2º A União, os Estados, o Distrito Federal e os Municípios aplicarão, anualmente, em ações e serviços públicos de saúde recursos mínimos derivados da aplicação de percentuais calculados sobre:\nII - no caso dos Estados e do Distrito Federal, o produto da arrecadação dos impostos a que se referem os arts. 155 e 156-A e dos recursos de que tratam os arts. 157 e 159, I, \"a\", e II, deduzidas as parcelas que forem transferidas aos respectivos Municípios;"],"origin":"authorial","question":{"statement":"§ 2º A União, os Estados, o Distrito Federal e os Municípios aplicarão, anualmente, em ações e serviços públicos de saúde recursos mínimos derivados da aplicação de percentuais calculados sobre:\nII - no caso dos Estados e do Distrito Federal, o produto da arrecadação dos impostos a que se referem os arts. 155 e 156-A e dos recursos de que tratam os arts. 157 e 159, I, \"a\", e II, incluídas as parcelas que forem transferidas aos respectivos Municípios;","answer":false,"explanation":"Na base dos Estados e do Distrito Federal, deduzem-se as parcelas transferidas aos respectivos Municípios.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0066","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 2º, caput e inciso III","number":"Art. 198, § 2º, caput e inciso III","title":"Constituição Federal de 1988","parts":["§ 2º A União, os Estados, o Distrito Federal e os Municípios aplicarão, anualmente, em ações e serviços públicos de saúde recursos mínimos derivados da aplicação de percentuais calculados sobre:\nIII - no caso dos Municípios e do Distrito Federal, o produto da arrecadação dos impostos a que se referem os arts. 156 e 156-A e dos recursos de que tratam os arts. 158 e 159, I, \"b\", e § 3º."],"origin":"authorial","question":{"statement":"§ 2º A União, os Estados, o Distrito Federal e os Municípios aplicarão, anualmente, em ações e serviços públicos de saúde recursos mínimos derivados da aplicação de percentuais calculados sobre:\nIII - no caso dos Municípios e do Distrito Federal, o produto da arrecadação dos impostos a que se referem os arts. 156 e 156-A e dos recursos de que tratam os arts. 158 e 159, I, \"b\", e § 3º.","answer":true,"explanation":"A base de Municípios e Distrito Federal usa os impostos e transferências especificados no inciso III, inclusive a referência ao art. 156-A.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0067","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 3º, caput e inciso I","number":"Art. 198, § 3º, caput e inciso I","title":"Constituição Federal de 1988","parts":["§ 3º Lei complementar, que será reavaliada pelo menos a cada cinco anos, estabelecerá:\nI - os percentuais de que tratam os incisos II e III do § 2º;"],"origin":"authorial","question":{"statement":"§ 3º Lei complementar, que será reavaliada pelo menos a cada dez anos, estabelecerá:\nI - os percentuais de que tratam os incisos II e III do § 2º;","answer":false,"explanation":"A lei complementar deve ser reavaliada ao menos a cada cinco anos e fixa os percentuais dos incisos II e III do § 2º.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0068","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 3º, caput e inciso II","number":"Art. 198, § 3º, caput e inciso II","title":"Constituição Federal de 1988","parts":["§ 3º Lei complementar, que será reavaliada pelo menos a cada cinco anos, estabelecerá:\nII – os critérios de rateio dos recursos da União vinculados à saúde destinados aos Estados, ao Distrito Federal e aos Municípios, e dos Estados destinados a seus respectivos Municípios, objetivando a progressiva redução das disparidades regionais;"],"origin":"authorial","question":{"statement":"§ 3º Lei complementar, que será reavaliada pelo menos a cada cinco anos, estabelecerá:\nII – os critérios de rateio dos recursos da União vinculados à saúde destinados aos Estados, ao Distrito Federal e aos Municípios, e dos Estados destinados a seus respectivos Municípios, objetivando a progressiva redução das disparidades regionais;","answer":true,"explanation":"Os critérios de rateio buscam redução progressiva das disparidades regionais.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0069","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 3º, caput e inciso III","number":"Art. 198, § 3º, caput e inciso III","title":"Constituição Federal de 1988","parts":["§ 3º Lei complementar, que será reavaliada pelo menos a cada cinco anos, estabelecerá:\nIII – as normas de fiscalização, avaliação e controle das despesas com saúde nas esferas federal, estadual, distrital e municipal;"],"origin":"authorial","question":{"statement":"§ 3º Lei complementar, que será reavaliada pelo menos a cada cinco anos, estabelecerá:\nIII – as normas de fiscalização, avaliação e controle das despesas com saúde nas esferas federal, estadual, distrital e municipal;","answer":true,"explanation":"A lei complementar estabelece normas de fiscalização, avaliação e controle das despesas em todas as esferas indicadas.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0070","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 4º","number":"Art. 198, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º Os gestores locais do sistema único de saúde poderão admitir agentes comunitários de saúde e agentes de combate às endemias por meio de processo seletivo público, de acordo com a natureza e complexidade de suas atribuições e requisitos específicos para sua atuação."],"origin":"authorial","question":{"statement":"§ 4º Os gestores locais do sistema único de saúde poderão admitir agentes comunitários de saúde e agentes de combate às endemias por meio de concurso público de provas e títulos, de acordo com a natureza e complexidade de suas atribuições e requisitos específicos para sua atuação.","answer":false,"explanation":"Para esses agentes, o § 4º prevê admissão por processo seletivo público, com requisitos próprios.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0071","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 5º","number":"Art. 198, § 5º","title":"Constituição Federal de 1988","parts":["§ 5º Lei federal disporá sobre o regime jurídico, o piso salarial profissional nacional, as diretrizes para os Planos de Carreira e a regulamentação das atividades de agente comunitário de saúde e agente de combate às endemias, competindo à União, nos termos da lei, prestar assistência financeira complementar aos Estados, ao Distrito Federal e aos Municípios, para o cumprimento do referido piso salarial."],"origin":"authorial","question":{"statement":"§ 5º Lei federal disporá sobre o regime jurídico, o piso salarial profissional nacional, as diretrizes para os Planos de Carreira e a regulamentação das atividades de agente comunitário de saúde e agente de combate às endemias, competindo à União, nos termos da lei, prestar assistência financeira complementar aos Estados, ao Distrito Federal e aos Municípios, para o cumprimento do referido piso salarial.","answer":true,"explanation":"A lei federal trata do regime, piso, planos de carreira e atividades dos agentes; a União presta assistência complementar para o piso.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0072","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 6º","number":"Art. 198, § 6º","title":"Constituição Federal de 1988","parts":["§ 6º Além das hipóteses previstas no § 1º do art. 41 e no § 4º do art. 169 da Constituição Federal, o servidor que exerça funções equivalentes às de agente comunitário de saúde ou de agente de combate às endemias poderá perder o cargo em caso de descumprimento dos requisitos específicos, fixados em lei, para o seu exercício."],"origin":"authorial","question":{"statement":"§ 6º Além das hipóteses previstas no § 1º do art. 41 e no § 4º do art. 169 da Constituição Federal, o servidor que exerça funções equivalentes às de agente comunitário de saúde ou de agente de combate às endemias poderá perder o cargo em caso de descumprimento dos requisitos específicos, fixados em regulamento, para o seu exercício.","answer":false,"explanation":"A perda do cargo nessa hipótese depende de descumprimento de requisitos específicos fixados em lei.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0073","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 7º","number":"Art. 198, § 7º","title":"Constituição Federal de 1988","parts":["§ 7º O vencimento dos agentes comunitários de saúde e dos agentes de combate às endemias fica sob responsabilidade da União, e cabe aos Estados, ao Distrito Federal e aos Municípios estabelecer, além de outros consectários e vantagens, incentivos, auxílios, gratificações e indenizações, a fim de valorizar o trabalho desses profissionais."],"origin":"authorial","question":{"statement":"§ 7º O vencimento dos agentes comunitários de saúde e dos agentes de combate às endemias fica sob responsabilidade da União, e cabe aos Estados, ao Distrito Federal e aos Municípios estabelecer, além de outros consectários e vantagens, incentivos, auxílios, gratificações e indenizações, a fim de valorizar o trabalho desses profissionais.","answer":true,"explanation":"A União responde pelo vencimento, enquanto os demais entes estabelecem incentivos, auxílios, gratificações e indenizações.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0074","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 8º","number":"Art. 198, § 8º","title":"Constituição Federal de 1988","parts":["§ 8º Os recursos destinados ao pagamento do vencimento dos agentes comunitários de saúde e dos agentes de combate às endemias serão consignados no orçamento geral da União com dotação própria e exclusiva."],"origin":"authorial","question":{"statement":"§ 8º Os recursos destinados ao pagamento do vencimento dos agentes comunitários de saúde e dos agentes de combate às endemias serão consignados no orçamento geral dos Municípios com dotação própria e exclusiva.","answer":false,"explanation":"Os recursos destinados ao vencimento são consignados no orçamento geral da União, em dotação própria e exclusiva.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0075","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 9º","number":"Art. 198, § 9º","title":"Constituição Federal de 1988","parts":["§ 9º O vencimento dos agentes comunitários de saúde e dos agentes de combate às endemias não será inferior a 2 (dois) salários mínimos, repassados pela União aos Municípios, aos Estados e ao Distrito Federal."],"origin":"authorial","question":{"statement":"§ 9º O vencimento dos agentes comunitários de saúde e dos agentes de combate às endemias não será inferior a 2 (dois) salários mínimos, repassados pela União aos Municípios, aos Estados e ao Distrito Federal.","answer":true,"explanation":"O vencimento dos agentes não será inferior a dois salários mínimos, repassados pela União aos entes indicados.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0076","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 10","number":"Art. 198, § 10","title":"Constituição Federal de 1988","parts":["§ 10. Os agentes comunitários de saúde e os agentes de combate às endemias terão também, em razão dos riscos inerentes às funções desempenhadas, aposentadoria especial e, somado aos seus vencimentos, adicional de insalubridade."],"origin":"authorial","question":{"statement":"§ 10. Os agentes comunitários de saúde e os agentes de combate às endemias terão também, em razão dos riscos inerentes às funções desempenhadas, aposentadoria especial e, somado aos seus vencimentos, adicional de periculosidade.","answer":false,"explanation":"A Constituição prevê aposentadoria especial e adicional de insalubridade em razão dos riscos das funções.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0077","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 11","number":"Art. 198, § 11","title":"Constituição Federal de 1988","parts":["§ 11. Os recursos financeiros repassados pela União aos Estados, ao Distrito Federal e aos Municípios para pagamento do vencimento ou de qualquer outra vantagem dos agentes comunitários de saúde e dos agentes de combate às endemias não serão objeto de inclusão no cálculo para fins do limite de despesa com pessoal."],"origin":"authorial","question":{"statement":"§ 11. Os recursos financeiros repassados pela União aos Estados, ao Distrito Federal e aos Municípios para pagamento do vencimento ou de qualquer outra vantagem dos agentes comunitários de saúde e dos agentes de combate às endemias não serão objeto de inclusão no cálculo para fins do limite de despesa com pessoal.","answer":true,"explanation":"Os repasses federais para vencimento ou outra vantagem dos agentes ficam fora do cálculo do limite de despesa com pessoal.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0078","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 12","number":"Art. 198, § 12","title":"Constituição Federal de 1988","parts":["§ 12. Lei federal instituirá pisos salariais profissionais nacionais para o enfermeiro, o técnico de enfermagem, o auxiliar de enfermagem e a parteira, a serem observados por pessoas jurídicas de direito público e de direito privado."],"origin":"authorial","question":{"statement":"§ 12. Lei federal instituirá pisos salariais profissionais nacionais para o enfermeiro, o técnico de enfermagem, o auxiliar de enfermagem e a parteira, a serem observados apenas por pessoas jurídicas de direito público.","answer":false,"explanation":"Os pisos nacionais das quatro categorias devem ser observados por pessoas jurídicas públicas e privadas.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0079","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 13","number":"Art. 198, § 13","title":"Constituição Federal de 1988","parts":["§ 13. A União, os Estados, o Distrito Federal e os Municípios, até o final do exercício financeiro em que for publicada a lei de que trata o § 12 deste artigo, adequarão a remuneração dos cargos ou dos respectivos planos de carreiras, quando houver, de modo a atender aos pisos estabelecidos para cada categoria profissional."],"origin":"authorial","question":{"statement":"§ 13. A União, os Estados, o Distrito Federal e os Municípios, até o final do exercício financeiro em que for publicada a lei de que trata o § 12 deste artigo, adequarão a remuneração dos cargos ou dos respectivos planos de carreiras, quando houver, de modo a atender aos pisos estabelecidos para cada categoria profissional.","answer":true,"explanation":"Os entes devem adequar remuneração ou planos de carreira até o fim do exercício da publicação da lei dos pisos.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0080","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 14","number":"Art. 198, § 14","title":"Constituição Federal de 1988","parts":["§ 14. Compete à União, nos termos da lei, prestar assistência financeira complementar aos Estados, ao Distrito Federal e aos Municípios e às entidades filantrópicas, bem como aos prestadores de serviços contratualizados que atendam, no mínimo, 60% (sessenta por cento) de seus pacientes pelo sistema único de saúde, para o cumprimento dos pisos salariais de que trata o § 12 deste artigo."],"origin":"authorial","question":{"statement":"§ 14. Compete à União, nos termos da lei, prestar assistência financeira complementar aos Estados, ao Distrito Federal e aos Municípios e às entidades filantrópicas, bem como aos prestadores de serviços contratualizados que atendam, no mínimo, 70% (setenta por cento) de seus pacientes pelo sistema único de saúde, para o cumprimento dos pisos salariais de que trata o § 12 deste artigo.","answer":false,"explanation":"Para os prestadores contratualizados, o patamar expresso de pacientes atendidos pelo SUS é de pelo menos 60%.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0081","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 15","number":"Art. 198, § 15","title":"Constituição Federal de 1988","parts":["§ 15. Os recursos federais destinados aos pagamentos da assistência financeira complementar aos Estados, ao Distrito Federal e aos Municípios e às entidades filantrópicas, bem como aos prestadores de serviços contratualizados que atendam, no mínimo, 60% (sessenta por cento) de seus pacientes pelo sistema único de saúde, para o cumprimento dos pisos salariais de que trata o § 12 deste artigo serão consignados no orçamento geral da União com dotação própria e exclusiva."],"origin":"authorial","question":{"statement":"§ 15. Os recursos federais destinados aos pagamentos da assistência financeira complementar aos Estados, ao Distrito Federal e aos Municípios e às entidades filantrópicas, bem como aos prestadores de serviços contratualizados que atendam, no mínimo, 60% (sessenta por cento) de seus pacientes pelo sistema único de saúde, para o cumprimento dos pisos salariais de que trata o § 12 deste artigo serão consignados no orçamento geral da União com dotação própria e exclusiva.","answer":true,"explanation":"A assistência financeira complementar para os pisos tem recursos federais em dotação própria e exclusiva no orçamento geral da União.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0082","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 199, caput","number":"Art. 199, caput","title":"Constituição Federal de 1988","parts":["Art. 199. A assistência à saúde é livre à iniciativa privada."],"origin":"authorial","question":{"statement":"Art. 199. A assistência à saúde é livre à iniciativa privada.","answer":true,"explanation":"O caput permite a atuação da iniciativa privada na assistência à saúde; a participação dessas instituições no SUS segue as condições do § 1º.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0083","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 199, § 1º","number":"Art. 199, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º As instituições privadas poderão participar de forma complementar do sistema único de saúde, segundo diretrizes deste, mediante contrato de direito público ou convênio, tendo preferência as entidades filantrópicas e as sem fins lucrativos."],"origin":"authorial","question":{"statement":"§ 1º As instituições privadas poderão participar de forma substitutiva do sistema único de saúde, segundo diretrizes deste, mediante contrato de direito público ou convênio, tendo preferência as entidades filantrópicas e as sem fins lucrativos.","answer":false,"explanation":"A participação privada no SUS é complementar, segundo suas diretrizes e mediante contrato de direito público ou convênio.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0084","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 199, § 2º","number":"Art. 199, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º É vedada a destinação de recursos públicos para auxílios ou subvenções às instituições privadas com fins lucrativos."],"origin":"authorial","question":{"statement":"§ 2º É vedada a destinação de recursos públicos para auxílios ou subvenções às instituições privadas com fins lucrativos.","answer":true,"explanation":"A vedação alcança auxílios e subvenções públicos às instituições privadas com fins lucrativos.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0085","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 199, § 3º","number":"Art. 199, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º - É vedada a participação direta ou indireta de empresas ou capitais estrangeiros na assistência à saúde no País, salvo nos casos previstos em lei."],"origin":"authorial","question":{"statement":"§ 3º - É vedada a participação direta ou indireta de empresas ou capitais estrangeiros na assistência à saúde no País, salvo nos casos previstos em decreto.","answer":false,"explanation":"A exceção para empresas ou capitais estrangeiros depende dos casos previstos em lei.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0086","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 199, § 4º","number":"Art. 199, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º A lei disporá sobre as condições e os requisitos que facilitem a remoção de órgãos, tecidos e substâncias humanas para fins de transplante, pesquisa e tratamento, bem como a coleta, processamento e transfusão de sangue e seus derivados, sendo vedado todo tipo de comercialização."],"origin":"authorial","question":{"statement":"§ 4º A lei disporá sobre as condições e os requisitos que facilitem a remoção de órgãos, tecidos e substâncias humanas para fins de transplante, pesquisa e tratamento, bem como a coleta, processamento e transfusão de sangue e seus derivados, sendo vedado todo tipo de comercialização.","answer":true,"explanation":"A lei disciplina remoção e procedimentos relativos a órgãos, tecidos e sangue; todo tipo de comercialização é vedado.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0087","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso I","number":"Art. 200, caput e inciso I","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nI - controlar e fiscalizar procedimentos, produtos e substâncias de interesse para a saúde e participar da produção de medicamentos, equipamentos, imunobiológicos, hemoderivados e outros insumos;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nI - controlar e fiscalizar procedimentos, produtos e substâncias de interesse para a saúde e exercer com exclusividade a produção de medicamentos, equipamentos, imunobiológicos, hemoderivados e outros insumos;","answer":false,"explanation":"O SUS participa da produção de medicamentos e outros insumos; o inciso não lhe confere exclusividade.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0088","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso II","number":"Art. 200, caput e inciso II","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nII - executar as ações de vigilância sanitária e epidemiológica, bem como as de saúde do trabalhador;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nII - executar as ações de vigilância sanitária e epidemiológica, bem como as de saúde do trabalhador;","answer":true,"explanation":"Vigilâncias sanitária e epidemiológica e saúde do trabalhador integram a competência executiva do SUS.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0089","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso III","number":"Art. 200, caput e inciso III","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nIII - ordenar a formação de recursos humanos na área de saúde;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nIII - ordenar a formação de recursos humanos na área de saúde;","answer":true,"explanation":"Compete ao SUS ordenar a formação de recursos humanos na área de saúde.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0090","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso IV","number":"Art. 200, caput e inciso IV","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nIV - participar da formulação da política e da execução das ações de saneamento básico;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nIV - participar apenas da execução das ações de saneamento básico;","answer":false,"explanation":"O SUS participa tanto da formulação da política quanto da execução das ações de saneamento básico.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0091","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso V","number":"Art. 200, caput e inciso V","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nV - incrementar, em sua área de atuação, o desenvolvimento científico e tecnológico e a inovação;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nV - incrementar, em sua área de atuação, o desenvolvimento científico e tecnológico e a inovação;","answer":true,"explanation":"Desenvolvimento científico e tecnológico e inovação constam da atribuição atual.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0092","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso VI","number":"Art. 200, caput e inciso VI","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nVI - fiscalizar e inspecionar alimentos, compreendido o controle de seu teor nutricional, bem como bebidas e águas para consumo humano;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nVI - fiscalizar e inspecionar alimentos, excluído o controle de seu teor nutricional, bem como bebidas e águas para consumo humano;","answer":false,"explanation":"A fiscalização dos alimentos compreende o controle do teor nutricional.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0093","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso VII","number":"Art. 200, caput e inciso VII","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nVII - participar do controle e fiscalização da produção, transporte, guarda e utilização de substâncias e produtos psicoativos, tóxicos e radioativos;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nVII - participar do controle e fiscalização da produção, transporte, guarda e utilização de substâncias e produtos psicoativos, tóxicos e radioativos;","answer":true,"explanation":"O SUS participa do controle e fiscalização das etapas e substâncias enumeradas, inclusive radioativas.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0094","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso VIII","number":"Art. 200, caput e inciso VIII","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nVIII - colaborar na proteção do meio ambiente, nele compreendido o do trabalho."],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nVIII - colaborar na proteção do meio ambiente, excluído o do trabalho.","answer":false,"explanation":"A proteção do meio ambiente na competência do SUS compreende o ambiente do trabalho.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0095","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, caput","number":"Art. 202, caput","title":"Constituição Federal de 1988","parts":["Art. 202. O regime de previdência privada, de caráter complementar e organizado de forma autônoma em relação ao regime geral de previdência social, será facultativo, baseado na constituição de reservas que garantam o benefício contratado, e regulado por lei complementar."],"origin":"authorial","question":{"statement":"Art. 202. O regime de previdência privada, de caráter complementar e organizado de forma autônoma em relação ao regime geral de previdência social, será facultativo, baseado na constituição de reservas que garantam o benefício contratado, e regulado por lei complementar.","answer":true,"explanation":"O regime complementar é facultativo, autônomo em relação ao RGPS, baseado em reservas e regulado por lei complementar.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0096","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, § 1º","number":"Art. 202, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º A lei complementar de que trata este artigo assegurará ao participante de planos de benefícios de entidades de previdência privada o pleno acesso às informações relativas à gestão de seus respectivos planos."],"origin":"authorial","question":{"statement":"§ 1º A lei complementar de que trata este artigo assegurará ao patrocinador de planos de benefícios de entidades de previdência privada o pleno acesso às informações relativas à gestão de seus respectivos planos.","answer":false,"explanation":"O pleno acesso às informações de gestão é assegurado ao participante dos planos.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0097","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, § 2º","number":"Art. 202, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º As contribuições do empregador, os benefícios e as condições contratuais previstas nos estatutos, regulamentos e planos de benefícios das entidades de previdência privada não integram o contrato de trabalho dos participantes, assim como, à exceção dos benefícios concedidos, não integram a remuneração dos participantes, nos termos da lei."],"origin":"authorial","question":{"statement":"§ 2º As contribuições do empregador, os benefícios e as condições contratuais previstas nos estatutos, regulamentos e planos de benefícios das entidades de previdência privada não integram o contrato de trabalho dos participantes, assim como, à exceção dos benefícios concedidos, não integram a remuneração dos participantes, nos termos da lei.","answer":true,"explanation":"As contribuições e condições contratuais não integram o contrato de trabalho, com a ressalva dos benefícios concedidos quanto à remuneração.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0098","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, § 3º","number":"Art. 202, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º É vedado o aporte de recursos a entidade de previdência privada pela União, Estados, Distrito Federal e Municípios, suas autarquias, fundações, empresas públicas, sociedades de economia mista e outras entidades públicas, salvo na qualidade de patrocinador, situação na qual, em hipótese alguma, sua contribuição normal poderá exceder a do segurado."],"origin":"authorial","question":{"statement":"§ 3º É vedado o aporte de recursos a entidade de previdência privada pela União, Estados, Distrito Federal e Municípios, suas autarquias, fundações, empresas públicas, sociedades de economia mista e outras entidades públicas, salvo na qualidade de patrocinador, situação na qual, sua contribuição normal poderá exceder a do segurado.","answer":false,"explanation":"O ente público só pode aportar como patrocinador e sua contribuição normal não pode exceder a do segurado.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0099","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, § 4º","number":"Art. 202, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º Lei complementar disciplinará a relação entre a União, Estados, Distrito Federal ou Municípios, inclusive suas autarquias, fundações, sociedades de economia mista e empresas controladas direta ou indiretamente, enquanto patrocinadores de planos de benefícios previdenciários, e as entidades de previdência complementar."],"origin":"authorial","question":{"statement":"§ 4º Lei complementar disciplinará a relação entre a União, Estados, Distrito Federal ou Municípios, inclusive suas autarquias, fundações, sociedades de economia mista e empresas controladas direta ou indiretamente, enquanto patrocinadores de planos de benefícios previdenciários, e as entidades de previdência complementar.","answer":true,"explanation":"Lei complementar disciplina a relação entre patrocinadores públicos indicados e entidades de previdência complementar.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0100","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, § 5º","number":"Art. 202, § 5º","title":"Constituição Federal de 1988","parts":["§ 5º A lei complementar de que trata o § 4º aplicar-se-á, no que couber, às empresas privadas permissionárias ou concessionárias de prestação de serviços públicos, quando patrocinadoras de planos de benefícios em entidades de previdência complementar."],"origin":"authorial","question":{"statement":"§ 5º A lei complementar de que trata o § 4º aplicar-se-á integralmente, às empresas privadas permissionárias ou concessionárias de prestação de serviços públicos, quando patrocinadoras de planos de benefícios em entidades de previdência complementar.","answer":false,"explanation":"A aplicação da lei complementar às concessionárias ou permissionárias privadas patrocinadoras ocorre no que couber.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0101","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, § 6º","number":"Art. 202, § 6º","title":"Constituição Federal de 1988","parts":["§ 6º Lei complementar estabelecerá os requisitos para a designação dos membros das diretorias das entidades fechadas de previdência complementar instituídas pelos patrocinadores de que trata o § 4º e disciplinará a inserção dos participantes nos colegiados e instâncias de decisão em que seus interesses sejam objeto de discussão e deliberação."],"origin":"authorial","question":{"statement":"§ 6º Lei complementar estabelecerá os requisitos para a designação dos membros das diretorias das entidades fechadas de previdência complementar instituídas pelos patrocinadores de que trata o § 4º e disciplinará a inserção dos participantes nos colegiados e instâncias de decisão em que seus interesses sejam objeto de discussão e deliberação.","answer":true,"explanation":"A lei complementar regula designação de diretorias e inserção dos participantes nos colegiados pertinentes.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0102","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 203, caput","number":"Art. 203, caput","title":"Constituição Federal de 1988","parts":["Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:"],"origin":"authorial","question":{"statement":"Art. 203. A assistência social será prestada a quem dela necessitar, mediante contribuição à seguridade social, e tem por objetivos:","answer":false,"explanation":"A assistência social atende quem dela necessitar sem exigir contribuição à seguridade social.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0103","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 203, caput e incisos I e II","number":"Art. 203, caput e incisos I e II","title":"Constituição Federal de 1988","parts":["Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nI - a proteção à família, à maternidade, à infância, à adolescência e à velhice;\nII - o amparo às crianças e adolescentes carentes;"],"origin":"authorial","question":{"statement":"Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nI - a proteção à família, à maternidade, à infância, à adolescência e à velhice;\nII - o amparo às crianças e adolescentes carentes;","answer":true,"explanation":"Proteção dos grupos enumerados e amparo a crianças e adolescentes carentes são objetivos distintos.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0104","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 203, caput e inciso III","number":"Art. 203, caput e inciso III","title":"Constituição Federal de 1988","parts":["Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nIII - a promoção da integração ao mercado de trabalho;"],"origin":"authorial","question":{"statement":"Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nIII - a promoção da integração ao mercado de trabalho;","answer":true,"explanation":"A promoção da integração ao mercado de trabalho é objetivo expresso da assistência social.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0105","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 203, caput e inciso IV","number":"Art. 203, caput e inciso IV","title":"Constituição Federal de 1988","parts":["Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nIV - a habilitação e reabilitação das pessoas portadoras de deficiência e a promoção de sua integração à vida comunitária;"],"origin":"authorial","question":{"statement":"Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nIV - a habilitação e reabilitação das pessoas portadoras de deficiência e a promoção de sua integração exclusiva ao mercado de trabalho;","answer":false,"explanation":"O inciso IV prevê integração à vida comunitária das pessoas portadoras de deficiência.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0106","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 203, caput e inciso V","number":"Art. 203, caput e inciso V","title":"Constituição Federal de 1988","parts":["Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nV - a garantia de um salário mínimo de benefício mensal à pessoa portadora de deficiência e ao idoso que comprovem não possuir meios de prover à própria manutenção ou de tê-la provida por sua família, conforme dispuser a lei."],"origin":"authorial","question":{"statement":"Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nV - a garantia de um salário mínimo de benefício mensal à pessoa portadora de deficiência e ao idoso que comprovem não possuir meios de prover à própria manutenção ou de tê-la provida por sua família, conforme dispuser a lei.","answer":true,"explanation":"O benefício mensal de um salário mínimo depende das condições de deficiência ou idade, insuficiência de meios próprios ou familiares e da lei.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0107","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 203, caput e inciso VI","number":"Art. 203, caput e inciso VI","title":"Constituição Federal de 1988","parts":["Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nVI - a redução da vulnerabilidade socioeconômica de famílias em situação de pobreza ou de extrema pobreza."],"origin":"authorial","question":{"statement":"Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nVI - a redução da vulnerabilidade socioeconômica de famílias em situação de pobreza e de extrema pobreza.","answer":false,"explanation":"A redução da vulnerabilidade alcança famílias em pobreza ou extrema pobreza, de forma alternativa.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0108","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 204, caput e inciso I","number":"Art. 204, caput e inciso I","title":"Constituição Federal de 1988","parts":["Art. 204. As ações governamentais na área da assistência social serão realizadas com recursos do orçamento da seguridade social, previstos no art. 195, além de outras fontes, e organizadas com base nas seguintes diretrizes:\nI - descentralização político-administrativa, cabendo a coordenação e as normas gerais à esfera federal e a coordenação e a execução dos respectivos programas às esferas estadual e municipal, bem como a entidades beneficentes e de assistência social;"],"origin":"authorial","question":{"statement":"Art. 204. As ações governamentais na área da assistência social serão realizadas com recursos do orçamento da seguridade social, previstos no art. 195, além de outras fontes, e organizadas com base nas seguintes diretrizes:\nI - descentralização político-administrativa, cabendo a coordenação e as normas gerais à esfera federal e a coordenação e a execução dos respectivos programas à esfera federal, bem como a entidades beneficentes e de assistência social;","answer":false,"explanation":"A coordenação e as normas gerais cabem à esfera federal; a coordenação e execução dos programas cabem às esferas estadual e municipal e às entidades indicadas.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0109","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 204, caput e inciso II","number":"Art. 204, caput e inciso II","title":"Constituição Federal de 1988","parts":["Art. 204. As ações governamentais na área da assistência social serão realizadas com recursos do orçamento da seguridade social, previstos no art. 195, além de outras fontes, e organizadas com base nas seguintes diretrizes:\nII - participação da população, por meio de organizações representativas, na formulação das políticas e no controle das ações em todos os níveis."],"origin":"authorial","question":{"statement":"Art. 204. As ações governamentais na área da assistência social serão realizadas com recursos do orçamento da seguridade social, previstos no art. 195, além de outras fontes, e organizadas com base nas seguintes diretrizes:\nII - participação da população, por meio de organizações representativas, na formulação das políticas e no controle das ações em todos os níveis.","answer":true,"explanation":"A população participa por organizações representativas da formulação das políticas e do controle das ações em todos os níveis.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0110","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 204, parágrafo único, inciso I","number":"Art. 204, parágrafo único, inciso I","title":"Constituição Federal de 1988","parts":["Parágrafo único. É facultado aos Estados e ao Distrito Federal vincular a programa de apoio à inclusão e promoção social até cinco décimos por cento de sua receita tributária líquida, vedada a aplicação desses recursos no pagamento de:\nI - despesas com pessoal e encargos sociais;"],"origin":"authorial","question":{"statement":"Parágrafo único. É facultado aos Estados e ao Distrito Federal vincular a programa de apoio à inclusão e promoção social até um por cento de sua receita tributária líquida, vedada a aplicação desses recursos no pagamento de:\nI - despesas com pessoal e encargos sociais;","answer":false,"explanation":"A vinculação facultativa para Estados e Distrito Federal tem teto de cinco décimos por cento da receita tributária líquida e não pode pagar pessoal.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0111","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 204, parágrafo único, incisos II e III","number":"Art. 204, parágrafo único, incisos II e III","title":"Constituição Federal de 1988","parts":["Parágrafo único. É facultado aos Estados e ao Distrito Federal vincular a programa de apoio à inclusão e promoção social até cinco décimos por cento de sua receita tributária líquida, vedada a aplicação desses recursos no pagamento de:\nII - serviço da dívida;\nIII - qualquer outra despesa corrente não vinculada diretamente aos investimentos ou ações apoiados."],"origin":"authorial","question":{"statement":"Parágrafo único. É facultado aos Estados e ao Distrito Federal vincular a programa de apoio à inclusão e promoção social até cinco décimos por cento de sua receita tributária líquida, vedada a aplicação desses recursos no pagamento de:\nII - serviço da dívida;\nIII - qualquer outra despesa corrente não vinculada diretamente aos investimentos ou ações apoiados.","answer":true,"explanation":"A receita vinculada não pode pagar o serviço da dívida nem outras despesas correntes sem vínculo direto com os investimentos ou ações apoiados.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0112","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, caput","number":"Art. 225, caput","title":"Constituição Federal de 1988","parts":["Art. 225. Todos têm direito ao meio ambiente ecologicamente equilibrado, bem de uso comum do povo e essencial à sadia qualidade de vida, impondo-se ao Poder Público e à coletividade o dever de defendê-lo e preservá-lo para as presentes e futuras gerações."],"origin":"authorial","question":{"statement":"Art. 225. Todos têm direito ao meio ambiente ecologicamente equilibrado, bem de uso comum do povo e essencial à sadia qualidade de vida, impondo-se exclusivamente ao Poder Público o dever de defendê-lo e preservá-lo para as presentes e futuras gerações.","answer":false,"explanation":"O dever de defesa e preservação cabe ao Poder Público e à coletividade, para presentes e futuras gerações.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0113","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, I","number":"Art. 225, § 1º, I","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nI - preservar e restaurar os processos ecológicos essenciais e prover o manejo ecológico das espécies e ecossistemas;"],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nI - preservar e restaurar os processos ecológicos essenciais e prover o manejo ecológico das espécies e ecossistemas;","answer":true,"explanation":"Incumbem ao Poder Público a preservação e restauração de processos ecológicos e o manejo ecológico de espécies e ecossistemas.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0114","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, II","number":"Art. 225, § 1º, II","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nII - preservar a diversidade e a integridade do patrimônio genético do País e fiscalizar as entidades dedicadas à pesquisa e manipulação de material genético;"],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nII - preservar a diversidade e a integridade do patrimônio genético do País e autorizar exclusivamente as entidades dedicadas à pesquisa e manipulação de material genético;","answer":false,"explanation":"O inciso manda preservar o patrimônio genético e fiscalizar as entidades dedicadas à pesquisa e manipulação.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0115","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, III","number":"Art. 225, § 1º, III","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nIII - definir, em todas as unidades da Federação, espaços territoriais e seus componentes a serem especialmente protegidos, sendo a alteração e a supressão permitidas somente através de lei, vedada qualquer utilização que comprometa a integridade dos atributos que justifiquem sua proteção;"],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nIII - definir, em todas as unidades da Federação, espaços territoriais e seus componentes a serem especialmente protegidos, sendo a alteração e a supressão permitidas somente através de lei, vedada qualquer utilização que comprometa a integridade dos atributos que justifiquem sua proteção;","answer":true,"explanation":"A alteração e a supressão dos espaços protegidos só são permitidas por lei; a integridade dos atributos deve ser preservada.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0116","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, IV","number":"Art. 225, § 1º, IV","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nIV - exigir, na forma da lei, para instalação de obra ou atividade potencialmente causadora de significativa degradação do meio ambiente, estudo prévio de impacto ambiental, a que se dará publicidade;"],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nIV - exigir, na forma da lei, para instalação de obra ou atividade potencialmente causadora de significativa degradação do meio ambiente, estudo posterior de impacto ambiental, a que se dará publicidade;","answer":false,"explanation":"O estudo exigido para obra ou atividade potencialmente causadora de significativa degradação é prévio e público.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0117","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, V","number":"Art. 225, § 1º, V","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nV - controlar a produção, a comercialização e o emprego de técnicas, métodos e substâncias que comportem risco para a vida, a qualidade de vida e o meio ambiente;"],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nV - controlar a produção, a comercialização e o emprego de técnicas, métodos e substâncias que comportem risco para a vida, a qualidade de vida e o meio ambiente;","answer":true,"explanation":"O controle abrange produção, comercialização e emprego de técnicas, métodos e substâncias de risco.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0118","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, VI","number":"Art. 225, § 1º, VI","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nVI - promover a educação ambiental em todos os níveis de ensino e a conscientização pública para a preservação do meio ambiente;"],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nVI - promover a educação ambiental apenas no ensino básico e a conscientização pública para a preservação do meio ambiente;","answer":false,"explanation":"A educação ambiental deve ser promovida em todos os níveis de ensino, além da conscientização pública.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0119","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, VII","number":"Art. 225, § 1º, VII","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nVII - proteger a fauna e a flora, vedadas, na forma da lei, as práticas que coloquem em risco sua função ecológica, provoquem a extinção de espécies ou submetam os animais a crueldade."],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nVII - proteger a fauna e a flora, vedadas, na forma da lei, as práticas que coloquem em risco sua função ecológica, provoquem a extinção de espécies ou submetam os animais a crueldade.","answer":true,"explanation":"A proteção da fauna e flora veda práticas que ameacem sua função ecológica, extingam espécies ou submetam animais à crueldade.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0120","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, VIII","number":"Art. 225, § 1º, VIII","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nVIII - manter regime fiscal favorecido para os biocombustíveis e para o hidrogênio de baixa emissão de carbono, na forma de lei complementar, a fim de assegurar-lhes tributação inferior à incidente sobre os combustíveis fósseis, capaz de garantir diferencial competitivo em relação a estes, especialmente em relação às contribuições de que tratam o art. 195, I, \"b\", IV e V, e o art. 239 e aos impostos a que se referem os arts. 155, II, e 156-A."],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nVIII - manter regime fiscal favorecido exclusivamente para os biocombustíveis, na forma de lei complementar, a fim de assegurar-lhes tributação inferior à incidente sobre os combustíveis fósseis, capaz de garantir diferencial competitivo em relação a estes, especialmente em relação às contribuições de que tratam o art. 195, I, \"b\", IV e V, e o art. 239 e aos impostos a que se referem os arts. 155, II, e 156-A.","answer":false,"explanation":"O regime fiscal favorecido alcança biocombustíveis e hidrogênio de baixa emissão de carbono, na forma de lei complementar.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0121","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 2º","number":"Art. 225, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º Aquele que explorar recursos minerais fica obrigado a recuperar o meio ambiente degradado, de acordo com solução técnica exigida pelo órgão público competente, na forma da lei."],"origin":"authorial","question":{"statement":"§ 2º Aquele que explorar recursos minerais fica obrigado a recuperar o meio ambiente degradado, de acordo com solução técnica exigida pelo órgão público competente, na forma da lei.","answer":true,"explanation":"Quem explora recursos minerais deve recuperar o ambiente degradado conforme solução técnica exigida pelo órgão competente.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0122","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 3º","number":"Art. 225, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º As condutas e atividades consideradas lesivas ao meio ambiente sujeitarão os infratores, pessoas físicas ou jurídicas, a sanções penais e administrativas, independentemente da obrigação de reparar os danos causados."],"origin":"authorial","question":{"statement":"§ 3º As condutas e atividades consideradas lesivas ao meio ambiente sujeitarão os infratores, pessoas físicas ou jurídicas, a sanções penais e administrativas, em substituição à obrigação de reparar os danos causados.","answer":false,"explanation":"As sanções penais e administrativas não afastam a obrigação de reparar o dano ambiental.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0123","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 4º","number":"Art. 225, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º A Floresta Amazônica brasileira, a Mata Atlântica, a Serra do Mar, o Pantanal Mato-Grossense e a Zona Costeira são patrimônio nacional, e sua utilização far-se-á, na forma da lei, dentro de condições que assegurem a preservação do meio ambiente, inclusive quanto ao uso dos recursos naturais."],"origin":"authorial","question":{"statement":"§ 4º A Floresta Amazônica brasileira, a Mata Atlântica, a Serra do Mar, o Pantanal Mato-Grossense e a Zona Costeira são patrimônio nacional, e sua utilização far-se-á, na forma da lei, dentro de condições que assegurem a preservação do meio ambiente, inclusive quanto ao uso dos recursos naturais.","answer":true,"explanation":"Os biomas e áreas enumerados são patrimônio nacional; a utilização depende de condições legais de preservação.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0124","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 5º","number":"Art. 225, § 5º","title":"Constituição Federal de 1988","parts":["§ 5º São indisponíveis as terras devolutas ou arrecadadas pelos Estados, por ações discriminatórias, necessárias à proteção dos ecossistemas naturais."],"origin":"authorial","question":{"statement":"§ 5º São indisponíveis as terras devolutas ou arrecadadas pela União, por ações discriminatórias, necessárias à proteção dos ecossistemas naturais.","answer":false,"explanation":"A indisponibilidade recai nas terras devolutas ou arrecadadas pelos Estados, por ações discriminatórias, necessárias à proteção dos ecossistemas.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0125","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 6º","number":"Art. 225, § 6º","title":"Constituição Federal de 1988","parts":["§ 6º As usinas que operem com reator nuclear deverão ter sua localização definida em lei federal, sem o que não poderão ser instaladas."],"origin":"authorial","question":{"statement":"§ 6º As usinas que operem com reator nuclear deverão ter sua localização definida em lei federal, sem o que não poderão ser instaladas.","answer":true,"explanation":"A localização de usina com reator nuclear deve ser definida em lei federal antes de sua instalação.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0126","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 7º","number":"Art. 225, § 7º","title":"Constituição Federal de 1988","parts":["§ 7º Para fins do disposto na parte final do inciso VII do § 1º deste artigo, não se consideram cruéis as práticas desportivas que utilizem animais, desde que sejam manifestações culturais, conforme o § 1º do art. 215 desta Constituição Federal, registradas como bem de natureza imaterial integrante do patrimônio cultural brasileiro, devendo ser regulamentadas por lei específica que assegure o bem-estar dos animais envolvidos."],"origin":"authorial","question":{"statement":"§ 7º Para fins do disposto na parte final do inciso VII do § 1º deste artigo, não se consideram cruéis as práticas desportivas que utilizem animais, desde que sejam manifestações culturais, conforme o § 1º do art. 215 desta Constituição Federal, reconhecidas como bem de natureza imaterial integrante do patrimônio cultural brasileiro, devendo ser regulamentadas por lei específica que assegure o bem-estar dos animais envolvidos.","answer":false,"explanation":"A exceção exige registro como bem imaterial do patrimônio cultural brasileiro e lei específica de proteção ao bem-estar animal.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0127","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, caput","number":"Art. 226, caput","title":"Constituição Federal de 1988","parts":["Art. 226. A família, base da sociedade, tem especial proteção do Estado."],"origin":"authorial","question":{"statement":"Art. 226. A família, base da sociedade, tem especial proteção do Estado.","answer":true,"explanation":"A família é base da sociedade e recebe proteção especial do Estado.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0128","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 1º","number":"Art. 226, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º O casamento é civil e gratuita a celebração."],"origin":"authorial","question":{"statement":"§ 1º O casamento é civil e gratuito o registro civil.","answer":false,"explanation":"A gratuidade constitucional incide sobre a celebração do casamento civil.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0129","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 2º","number":"Art. 226, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º O casamento religioso tem efeito civil, nos termos da lei."],"origin":"authorial","question":{"statement":"§ 2º O casamento religioso tem efeito civil, nos termos da lei.","answer":true,"explanation":"O casamento religioso produz efeito civil nos termos da lei.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0130","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 3º","number":"Art. 226, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º Para efeito da proteção do Estado, é reconhecida a união estável entre o homem e a mulher como entidade familiar, devendo a lei facilitar sua conversão em casamento."],"origin":"authorial","question":{"statement":"§ 3º Para efeito da proteção do Estado, é reconhecida a união estável entre o homem e a mulher como entidade familiar, devendo a lei impedir sua conversão em casamento.","answer":false,"explanation":"A redação literal determina que a lei facilite a conversão da união estável em casamento. A aplicação a uniões homoafetivas é ressalva jurisprudencial separada.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0131","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 4º","number":"Art. 226, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º Entende-se, também, como entidade familiar a comunidade formada por qualquer dos pais e seus descendentes."],"origin":"authorial","question":{"statement":"§ 4º Entende-se, também, como entidade familiar a comunidade formada por qualquer dos pais e seus descendentes.","answer":true,"explanation":"A família monoparental formada por qualquer dos pais e seus descendentes também é entidade familiar.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0132","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 5º","number":"Art. 226, § 5º","title":"Constituição Federal de 1988","parts":["§ 5º Os direitos e deveres referentes à sociedade conjugal são exercidos igualmente pelo homem e pela mulher."],"origin":"authorial","question":{"statement":"§ 5º Os direitos e deveres referentes à sociedade conjugal são exercidos preferencialmente pelo homem.","answer":false,"explanation":"Direitos e deveres da sociedade conjugal são exercidos igualmente pelo homem e pela mulher.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0133","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 6º","number":"Art. 226, § 6º","title":"Constituição Federal de 1988","parts":["§ 6º O casamento civil pode ser dissolvido pelo divórcio."],"origin":"authorial","question":{"statement":"§ 6º O casamento civil pode ser dissolvido pelo divórcio.","answer":true,"explanation":"O texto vigente admite a dissolução do casamento civil pelo divórcio, sem inserir prazo de separação.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0134","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 7º","number":"Art. 226, § 7º","title":"Constituição Federal de 1988","parts":["§ 7º Fundado nos princípios da dignidade da pessoa humana e da paternidade responsável, o planejamento familiar é livre decisão do casal, competindo ao Estado propiciar recursos educacionais e científicos para o exercício desse direito, vedada qualquer forma coercitiva por parte de instituições oficiais ou privadas."],"origin":"authorial","question":{"statement":"§ 7º Fundado nos princípios da dignidade da pessoa humana e da paternidade responsável, o planejamento familiar é decisão exclusiva do Estado, competindo ao Estado propiciar recursos educacionais e científicos para o exercício desse direito, vedada qualquer forma coercitiva por parte de instituições oficiais ou privadas.","answer":false,"explanation":"O planejamento familiar é livre decisão do casal; o Estado propicia recursos e nenhuma instituição pode coagir.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0135","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 8º","number":"Art. 226, § 8º","title":"Constituição Federal de 1988","parts":["§ 8º O Estado assegurará a assistência à família na pessoa de cada um dos que a integram, criando mecanismos para coibir a violência no âmbito de suas relações."],"origin":"authorial","question":{"statement":"§ 8º O Estado assegurará a assistência à família na pessoa de cada um dos que a integram, criando mecanismos para coibir a violência no âmbito de suas relações.","answer":true,"explanation":"A assistência estatal alcança cada integrante da família e inclui mecanismos para coibir violência em suas relações.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0136","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, caput","number":"Art. 227, caput","title":"Constituição Federal de 1988","parts":["Art. 227. É dever da família, da sociedade e do Estado assegurar à criança, ao adolescente e ao jovem, com absoluta prioridade, o direito à vida, à saúde, à alimentação, à educação, ao lazer, à profissionalização, à cultura, à dignidade, ao respeito, à liberdade e à convivência familiar e comunitária, além de colocá-los a salvo de toda forma de negligência, discriminação, exploração, violência, crueldade e opressão."],"origin":"authorial","question":{"statement":"Art. 227. É dever da família, da sociedade e do Estado assegurar à criança e ao adolescente, com absoluta prioridade, o direito à vida, à saúde, à alimentação, à educação, ao lazer, à profissionalização, à cultura, à dignidade, ao respeito, à liberdade e à convivência familiar e comunitária, além de colocá-los a salvo de toda forma de negligência, discriminação, exploração, violência, crueldade e opressão.","answer":false,"explanation":"A prioridade absoluta e a proteção enunciadas no caput também se estendem ao jovem.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0137","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 1º, I","number":"Art. 227, § 1º, I","title":"Constituição Federal de 1988","parts":["§ 1º O Estado promoverá programas de assistência integral à saúde da criança, do adolescente e do jovem, admitida a participação de entidades não governamentais, mediante políticas específicas e obedecendo aos seguintes preceitos:\nI - aplicação de percentual dos recursos públicos destinados à saúde na assistência materno-infantil;"],"origin":"authorial","question":{"statement":"§ 1º O Estado promoverá programas de assistência integral à saúde da criança, do adolescente e do jovem, admitida a participação de entidades não governamentais, mediante políticas específicas e obedecendo aos seguintes preceitos:\nI - aplicação de percentual dos recursos públicos destinados à saúde na assistência materno-infantil;","answer":true,"explanation":"Há programas de assistência integral à saúde dos três grupos, com participação não governamental admitida, e percentual de recursos para assistência materno-infantil.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0138","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 1º, II","number":"Art. 227, § 1º, II","title":"Constituição Federal de 1988","parts":["§ 1º O Estado promoverá programas de assistência integral à saúde da criança, do adolescente e do jovem, admitida a participação de entidades não governamentais, mediante políticas específicas e obedecendo aos seguintes preceitos:\nII - criação de programas de prevenção e atendimento especializado para as pessoas portadoras de deficiência física, sensorial ou mental, bem como de integração social do adolescente e do jovem portador de deficiência, mediante o treinamento para o trabalho e a convivência, e a facilitação do acesso aos bens e serviços coletivos, com a eliminação de obstáculos arquitetônicos e de todas as formas de discriminação."],"origin":"authorial","question":{"statement":"§ 1º O Estado promoverá programas de assistência integral à saúde da criança, do adolescente e do jovem, admitida a participação de entidades não governamentais, mediante políticas específicas e obedecendo aos seguintes preceitos:\nII - criação de programas de prevenção e atendimento especializado para as pessoas portadoras de deficiência física, sensorial ou mental, bem como de integração social do adolescente e do jovem portador de deficiência, mediante o treinamento para o trabalho e a convivência, e a facilitação do acesso aos bens e serviços coletivos, com a eliminação apenas de obstáculos arquitetônicos.","answer":false,"explanation":"Os programas devem facilitar o acesso eliminando tanto obstáculos arquitetônicos como todas as formas de discriminação.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0139","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 2º","number":"Art. 227, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º A lei disporá sobre normas de construção dos logradouros e dos edifícios de uso público e de fabricação de veículos de transporte coletivo, a fim de garantir acesso adequado às pessoas portadoras de deficiência."],"origin":"authorial","question":{"statement":"§ 2º A lei disporá sobre normas de construção dos logradouros e dos edifícios de uso público e de fabricação de veículos de transporte coletivo, a fim de garantir acesso adequado às pessoas portadoras de deficiência.","answer":true,"explanation":"A lei disciplinará construção de espaços e edifícios públicos e fabricação de transporte coletivo para acesso adequado das pessoas com deficiência.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0140","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, I","number":"Art. 227, § 3º, I","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nI - idade mínima de quatorze anos para admissão ao trabalho, observado o disposto no art. 7º, XXXIII;"],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nI - idade mínima de quatorze anos para admissão ao trabalho, independentemente do disposto no art. 7º, XXXIII;","answer":false,"explanation":"A idade de quatorze anos se subordina ao art. 7º, XXXIII, que disciplina a aprendizagem e a vedação geral de trabalho ao menor de dezesseis.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0141","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, II","number":"Art. 227, § 3º, II","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nII - garantia de direitos previdenciários e trabalhistas;"],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nII - garantia de direitos previdenciários e trabalhistas;","answer":true,"explanation":"A proteção especial compreende a garantia de direitos previdenciários e trabalhistas.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0142","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, III","number":"Art. 227, § 3º, III","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nIII - garantia de acesso do trabalhador adolescente e jovem à escola;"],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nIII - garantia de acesso apenas do trabalhador adolescente à escola;","answer":false,"explanation":"O acesso à escola é garantido ao trabalhador adolescente e jovem.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0143","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, IV","number":"Art. 227, § 3º, IV","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nIV - garantia de pleno e formal conhecimento da atribuição de ato infracional, igualdade na relação processual e defesa técnica por profissional habilitado, segundo dispuser a legislação tutelar específica;"],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nIV - garantia de pleno e formal conhecimento da atribuição de ato infracional, igualdade na relação processual e defesa técnica por profissional habilitado, segundo dispuser a legislação tutelar específica;","answer":true,"explanation":"A atribuição de ato infracional exige conhecimento pleno e formal, igualdade processual e defesa técnica habilitada.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0144","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, V","number":"Art. 227, § 3º, V","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nV - obediência aos princípios de brevidade, excepcionalidade e respeito à condição peculiar de pessoa em desenvolvimento, quando da aplicação de qualquer medida privativa da liberdade;"],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nV - obediência aos princípios de brevidade, excepcionalidade e respeito à condição peculiar de pessoa em desenvolvimento, quando da aplicação de medidas meramente educativas sem privação da liberdade;","answer":false,"explanation":"Brevidade, excepcionalidade e condição peculiar regem qualquer medida privativa de liberdade.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0145","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, VI","number":"Art. 227, § 3º, VI","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nVI - estímulo do Poder Público, através de assistência jurídica, incentivos fiscais e subsídios, nos termos da lei, ao acolhimento, sob a forma de guarda, de criança ou adolescente órfão ou abandonado;"],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nVI - estímulo do Poder Público, através de assistência jurídica, incentivos fiscais e subsídios, nos termos da lei, ao acolhimento, sob a forma de guarda, de criança ou adolescente órfão ou abandonado;","answer":true,"explanation":"O estímulo estatal é ao acolhimento em guarda da criança ou adolescente órfão ou abandonado, mediante os instrumentos previstos.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0146","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, VII","number":"Art. 227, § 3º, VII","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nVII - programas de prevenção e atendimento especializado à criança, ao adolescente e ao jovem dependente de entorpecentes e drogas afins."],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nVII - programas de prevenção e atendimento especializado somente ao adolescente dependente de entorpecentes e drogas afins.","answer":false,"explanation":"Programas de prevenção e atendimento especializado a dependentes de entorpecentes alcançam criança, adolescente e jovem.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0147","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 4º","number":"Art. 227, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º A lei punirá severamente o abuso, a violência e a exploração sexual da criança e do adolescente."],"origin":"authorial","question":{"statement":"§ 4º A lei punirá severamente o abuso, a violência e a exploração sexual da criança e do adolescente.","answer":true,"explanation":"A lei deve punir severamente abuso, violência e exploração sexual de criança e adolescente.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0148","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 5º","number":"Art. 227, § 5º","title":"Constituição Federal de 1988","parts":["§ 5º A adoção será assistida pelo Poder Público, na forma da lei, que estabelecerá casos e condições de sua efetivação por parte de estrangeiros."],"origin":"authorial","question":{"statement":"§ 5º A adoção será assistida pelo Poder Público, na forma da lei, que estabelecerá casos e condições de sua efetivação exclusivamente por parte de brasileiros.","answer":false,"explanation":"A lei estabelecerá casos e condições de adoção por estrangeiros, sob assistência do Poder Público.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0149","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 6º","number":"Art. 227, § 6º","title":"Constituição Federal de 1988","parts":["§ 6º Os filhos, havidos ou não da relação do casamento, ou por adoção, terão os mesmos direitos e qualificações, proibidas quaisquer designações discriminatórias relativas à filiação."],"origin":"authorial","question":{"statement":"§ 6º Os filhos, havidos ou não da relação do casamento, ou por adoção, terão os mesmos direitos e qualificações, proibidas quaisquer designações discriminatórias relativas à filiação.","answer":true,"explanation":"Filhos matrimoniais, extramatrimoniais ou adotivos têm direitos e qualificações iguais, sem designações discriminatórias.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0150","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 7º","number":"Art. 227, § 7º","title":"Constituição Federal de 1988","parts":["§ 7º No atendimento dos direitos da criança e do adolescente levar-se- á em consideração o disposto no art. 204."],"origin":"authorial","question":{"statement":"§ 7º No atendimento dos direitos da criança e do adolescente levar-se- á em consideração o disposto no art. 198.","answer":false,"explanation":"A política de atendimento dos direitos de crianças e adolescentes considera as diretrizes de assistência social do art. 204.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0151","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 8º, I","number":"Art. 227, § 8º, I","title":"Constituição Federal de 1988","parts":["§ 8º A lei estabelecerá:\nI - o estatuto da juventude, destinado a regular os direitos dos jovens;"],"origin":"authorial","question":{"statement":"§ 8º A lei estabelecerá:\nI - o estatuto da juventude, destinado a regular os direitos dos jovens;","answer":true,"explanation":"A lei estabelecerá estatuto da juventude para regular direitos dos jovens.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0152","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 8º, II","number":"Art. 227, § 8º, II","title":"Constituição Federal de 1988","parts":["§ 8º A lei estabelecerá:\nII - o plano nacional de juventude, de duração decenal, visando à articulação das várias esferas do poder público para a execução de políticas públicas."],"origin":"authorial","question":{"statement":"§ 8º A lei estabelecerá:\nII - o plano nacional de juventude, de duração quadrienal, visando à articulação das várias esferas do poder público para a execução de políticas públicas.","answer":false,"explanation":"O plano nacional de juventude tem duração decenal e articula esferas do poder público.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0153","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 228, caput","number":"Art. 228, caput","title":"Constituição Federal de 1988","parts":["Art. 228. São penalmente inimputáveis os menores de dezoito anos, sujeitos às normas da legislação especial."],"origin":"authorial","question":{"statement":"Art. 228. São penalmente inimputáveis os menores de dezoito anos, sujeitos às normas da legislação especial.","answer":true,"explanation":"A inimputabilidade penal é dos menores de dezoito anos, sujeitos à legislação especial.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0154","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 229, caput","number":"Art. 229, caput","title":"Constituição Federal de 1988","parts":["Art. 229. Os pais têm o dever de assistir, criar e educar os filhos menores, e os filhos maiores têm o dever de ajudar e amparar os pais na velhice, carência ou enfermidade."],"origin":"authorial","question":{"statement":"Art. 229. Os pais têm o dever de assistir, criar e educar os filhos menores, e os filhos menores têm o dever de ajudar e amparar os pais na velhice, carência ou enfermidade.","answer":false,"explanation":"O dever recíproco de ajuda aos pais na velhice, carência ou enfermidade recai sobre os filhos maiores.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0155","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 230, caput","number":"Art. 230, caput","title":"Constituição Federal de 1988","parts":["Art. 230. A família, a sociedade e o Estado têm o dever de amparar as pessoas idosas, assegurando sua participação na comunidade, defendendo sua dignidade e bem-estar e garantindo-lhes o direito à vida."],"origin":"authorial","question":{"statement":"Art. 230. A família, a sociedade e o Estado têm o dever de amparar as pessoas idosas, assegurando sua participação na comunidade, defendendo sua dignidade e bem-estar e garantindo-lhes o direito à vida.","answer":true,"explanation":"Família, sociedade e Estado têm dever conjunto de amparo às pessoas idosas, com as garantias expressas.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0156","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 230, § 1º","number":"Art. 230, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º Os programas de amparo aos idosos serão executados preferencialmente em seus lares."],"origin":"authorial","question":{"statement":"§ 1º Os programas de amparo aos idosos serão executados exclusivamente em instituições especializadas.","answer":false,"explanation":"Os programas de amparo aos idosos são executados preferencialmente nos lares deles.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0157","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 230, § 2º","number":"Art. 230, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º Aos maiores de sessenta e cinco anos é garantida a gratuidade dos transportes coletivos urbanos."],"origin":"authorial","question":{"statement":"§ 2º Aos maiores de sessenta e cinco anos é garantida a gratuidade dos transportes coletivos urbanos.","answer":true,"explanation":"A gratuidade constitucional alcança os maiores de sessenta e cinco anos no transporte coletivo urbano.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial"}}];
